"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type PageTransitionPrimitiveProps = ComponentProps<typeof motion.div>;

export function PageTransitionPrimitive({ children, ...props }: PageTransitionPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      layout
      animate={reduceMotion ? undefined : {opacity: 1}}
      transition={reduceMotion ? { duration: 0.12 } : { type: "spring", stiffness: 260, damping: 28 }}
    >
      {children}
    </motion.div>
  );
}
